/**
 * Unit tests for org.apache.commons.codec.binary.Base64.encodeBase64String
 */
public class Base64_encodeBase64String_TriageGen1Test {







    @Test
    public void testEncodeBase64String_SpecialCharacters() {
        // Test with bytes that result in specific Base64 padding or characters
        byte[] input = new byte[]{(byte) 0x00, (byte) 0xFF, (byte) 0x00};
        // 00 FF 00 -> AP8A
        String actual = Base64.encodeBase64String(input);
        assertNotNull(actual);
        assertFalse("Result should not be empty for non-empty input", actual.isEmpty());
    }


}

