/**
 * Unit tests for org.apache.commons.codec.binary.Base64.encodeBase64String
 */
public class Base64_encodeBase64String_TriageGen1Test {









    @Test
    public void testEncodeBase64String_SingleByte() {
        // Test with a single byte to check padding logic
        byte[] input = new byte[]{(byte) 'A'};
        // 'A' is 0x41 -> Base64 is "QQ=="
        String expected = "QQ==";
        String actual = Base64.encodeBase64String(input);
        assertEquals("Single byte encoding failed to produce correct padding.", expected, actual);
    }
}
